brain_tool = BrainTool()  # 初始化大脑工具
query_processor = QueryProcessor()  # 初始化查询处理器 

from config.config import (
        RAG_RERANK_URL,
        TIME_OUT,
        THRESHOLD,
        MAX_LENGTH,
        DEBUG_MODE,
        SCHOOL_IDS,
        AUTOMATION_WITH_SCHOOLID,
        NODE_TO_PATHS_WITH_SCHOOLID,
        NODE_NAME_TO_NODE_WITH_SCHOOLID,
