class MultiRag:
    def __init__(
            self,
            logger=logger,
            time_out: int = TIME_OUT,
            threshold: float = THRESHOLD,
            max_length: int = MAX_LENGTH,
        ):
        self.logger = logger
        self.time_out = time_out
        self.threshold = threshold
        self.max_length = max_length
        self.compress = BM25Compressor()

    @calculate_execution_time(func_id='MULTI_RAG.RUN')
    def run(
            self, 
            text_list: List[Dict[str, Any]], 
            school_id: str = '-1',
            rewrite_type: str = 'general',
            knowledge_base_ids=[],
            use_fast: bool = False,
            structured_context: bool = False,
            use_graph_knowledge: bool = True,
            use_context_knowledge: bool = False,
            use_synonyms: bool = True,
            bg_prompt: str = '',
        ) -> Dict[str, Any]:
        query = query_processor.process(text_list[0]['text'])
        text_list = text_list[1:]
        knowledge_graph = {}
        is_rag, intent_list = determine_rag(query, school_id=school_id, return_intent=True)

        if is_rag:
            context = self.retrieve_structured_text(query, text_list) if structured_context else self.retrieve_related_text(query, text_list)
            context = query_processor.process(context) if context else ''

            if rewrite_type == 'policy' and len(knowledge_base_ids) > 0:
                context_knowledge = extract_knowledge(text_list) if use_context_knowledge else ''
                if use_graph_knowledge:
                    knowledge_graph = brain_tool.get_hits(
                            query_text=query, 
                            knowledge_base_id_list=knowledge_base_ids
                        )
                else:
                    knowledge_graph = 'None'

                context = f'{context}\nCONTEXT METAINFO：{context_knowledge}' if context_knowledge else context
                if knowledge_graph:
                    logger.log_info(f"【MULTI-RAG-KNOWLEDGE】ADDITION INFO ON KNOWLEDGE GRAPH: *********************{knowledge_graph}*********************")
                if context_knowledge:
                    logger.log_info(f"【MULTI-RAG-CONTEXT】ADDITION INFO ON CONTEXT GRAPH: *********************{context_knowledge}*********************")

            elif (rewrite_type == 'policy') and (school_id != '-1'):
                context_knowledge = extract_knowledge(text_list) if use_context_knowledge else ''
                if use_graph_knowledge:
                    knowledge_graph, keywords = merge_graph_path(
                            AUTOMATION_WITH_SCHOOLID[school_id], 
                            NODE_TO_PATHS_WITH_SCHOOLID[school_id], 
                            NODE_NAME_TO_NODE_WITH_SCHOOLID[school_id], 
                            [query, context],
                            [1, 0.3],
                            return_keywords=True,
                            use_synonyms=use_synonyms,
                        )
                    knowledge_graph = str(knowledge_graph) if knowledge_graph else ''
                else:
                    knowledge_graph = 'None'
                    keywords = []

                if keywords:
                    context += f"\nCONTEXT/QUERY中涉及专有名词(需保留在改写查询中)：{'、'.join(keywords)}"
                else:
                    combined_text = query + context
                    if len(combined_text) >= 20:
                        longest_repeating_substring = extract_longest_repeating_substring(combined_text)
                        if len(longest_repeating_substring) >= 4:
                            context += f"\nCONTEXT/QUERY中涉及专有名词(需保留在改写查询中)：{longest_repeating_substring}"

                context = f'{context}\nCONTEXT METAINFO：{context_knowledge}' if context_knowledge else context

                if knowledge_graph:
                    logger.log_info(f"【MULTI-RAG-KNOWLEDGE】ADDITION INFO ON KNOWLEDGE GRAPH: *********************{knowledge_graph}*********************")
                if context_knowledge:
                    logger.log_info(f"【MULTI-RAG-CONTEXT】ADDITION INFO ON CONTEXT GRAPH: *********************{context_knowledge}*********************")

            response, rewrite_queries = rewrite_query(
                    query=query, 
                    context=context, 
                    knowledge_graph=knowledge_graph, 
                    rewrite_type=rewrite_type,
                    use_fast=use_fast,
                    logger=logger,
                    bg_prompt=bg_prompt,
                )
            rewrite_queries, intent_list = self.adjust_rewrite_queries(rewrite_queries, intent_list)

            if school_id in SCHOOL_IDS:
                return info_extractor.generate_rewritten_queries_for_school(query, school_id, rewrite_queries, intent_list)

            if DEBUG_MODE == 1:
                if context and knowledge_graph:
                    prompt_type = 'with_context_category'
                elif context:
                    prompt_type = 'with_context'
                elif knowledge_graph:
                    prompt_type = 'with_category'
                else:
                    prompt_type = 'only_query'

                return {
                    'isRag': 1,
                    "query": query,
                    'reWriteText': rewrite_queries,
                    'knowledgeGraph': knowledge_graph,
                    'response': response,
                    'prompt_type': prompt_type
                }
            else:
                return {
                    'isRag': 1,
                    'reWriteText': rewrite_queries,
                }
        if DEBUG_MODE == 1:
            return {
                'isRag': 0,
                'query': query,
                'reWriteText': [{'text': query, 'type': 1}],
                'knowledgeGraph': knowledge_graph,
                'response': '',
                'prompt_type': 'only_query',
            }
        else:
            return {
                'isRag': 0,
                'reWriteText': [{'text': query, 'type': 1}],
            }

    @staticmethod
    def adjust_rewrite_queries(rewrite_queries, intent_list):
        if rewrite_queries:
            if len(intent_list) > len(rewrite_queries):
                intent_list = intent_list[:len(rewrite_queries)]
            else:
                intent_list = (intent_list * (len(rewrite_queries) // len(intent_list) + 1))
                intent_list = intent_list[:len(rewrite_queries)]
        else:
            rewrite_queries = [{'text': query, 'type': i + 1} for i, query in enumerate(intent_list)]
        return rewrite_queries, intent_list

    @calculate_execution_time(func_id='MULTI_RAG.RETRIEVE_STRUCTURED_TEXT')
    def retrieve_structured_text(self, query: str, context_list: List[Dict[str, Any]]) -> str:
        ret = construct_new_text_list(query, context_list, compressor=self.compress)
        return str(ret) + '（Notice：order越大，越接近当前query轮次）' if ret else ''

    @calculate_execution_time(func_id='MULTI_RAG.RETRIEVE_RELATED_TEXT')
    def retrieve_related_text(self, query: str, context_list: List[Dict[str, Any]]) -> str:
        # 如果上下文列表为空，返回空字符串
        if not context_list:
            return ""

        # 如果只有一个上下文，直接返回格式化后的内容
        if len(context_list) == 1:
            self.logger.log_info("【MULTI-RAG】检测到单一上下文")  # 记录日志
            return f"{context_list[0]['text']}:\n{context_list[0]['answer'][:self.max_length]}"

        # 构建完整的问答内容，包括所有上下文条目
        full_context_qa = "\n".join([
            f"ROUND: {item['order']}; <{item['text']}>: {item['answer']}"
            for item in context_list
        ])
        # 如果完整问答内容小于3000字符，返回它并附加提示
        if len(full_context_qa) < 3000:
            return full_context_qa + "\n(Notice: 查询更相关于后续轮次)"

        # 构建截断的问答内容，每个答案限制为500字符
        truncated_context_qa = "\n".join([
            f"ROUND: {item['order']}; <{item['text']}>: {item['answer'][:500]}"
            for item in context_list
        ])
        # 如果截断后的问答内容小于4096字符，返回它并附加提示
        if len(truncated_context_qa) < 4096:
            return truncated_context_qa + "\n(Notice: 查询更相关于后续轮次)"

        # 初始化处理后的检索文本
        processed_retrieved_text = ""

        # 遍历上下文列表，从每个上下文中提取相关段落
        for item in context_list:
            raw_text = item['answer']
            # 解析 Markdown 内容，提取标题、标题层级和段落
            headers, header_levels, paragraphs = process_markdown(raw_text)
            item['paragraphs'] = paragraphs  # 将段落信息存回上下文条目
            # 根据查询获取相关段落并拼接到检索文本中
            processed_retrieved_text += self.extract_related_paragraphs(query, headers, header_levels, paragraphs) + "\n"

        # 如果成功通过段落匹配提取到内容，返回处理后的结果
        if processed_retrieved_text:
            self.logger.log_info("【MULTI-RAG】通过段落匹配完成检索")  # 记录日志
            return f"{processed_retrieved_text}\n最后一轮: <{context_list[0]['text']}>:\n{context_list[0]['answer'][:self.max_length]}"

        # 如果段落匹配失败，回退到基于幻灯片的检索方法
        slide_retrieved_text = self.retrieve_by_slide(query, context_list)
        self.logger.log_info("【MULTI-RAG】通过幻灯片方法完成检索")  # 记录日志
        return f"{slide_retrieved_text}\n最后一轮: <{context_list[0]['text']}>:\n{context_list[0]['answer'][:self.max_length]}"


    def extract_related_paragraphs(self, query: str, headers: List[str], header_levels: List[int], paragraphs: List[str]) -> str:
        related_text = ""
        # 计算查询与每个标题的相似度
        similarities = [difflib.SequenceMatcher(None, query, header).ratio() for header in headers]

        # 遍历标题和标题层级，根据相似度提取相关段落
        for idx, (similarity, level) in enumerate(zip(similarities, header_levels)):
            if similarity > self.threshold:
                while idx < len(header_levels) and level < header_levels[idx]:
                    related_text += paragraphs[idx]
                    idx += 1

        return related_text.strip()

    def retrieve_by_rerank(self, query: str, text_list: List[Dict[str, Any]]) -> str:
        doc_list = []
        for idx, text_dict in enumerate(text_list):
            doc_list.append({"id": idx, "doc": text_dict['text']})
            for para in text_dict['paragraphs']:
                doc_list.append({"id": idx, "doc": para})

        params = {
            "query": query,
            "docList": doc_list,
            "model": "bge",
        }

        id_score_list = call_api(url=RAG_RERANK_URL, data=params)["data"]["resultList"]

        retrieved_text = ""
        for id_score in id_score_list:
            if id_score['score'] < self.threshold:
                break
            retrieved_text += doc_list[id_score['id']]['doc'] + "\n"

        return retrieved_text.strip()

    def retrieve_by_slide(self, query: str, text_list: List[Dict[str, Any]]) -> str:
        bm25fqa = BM25FQA(text_list)
        top_answer = bm25fqa.get_top_answers(query, top_n=3)
        return top_answer.strip()

